// ============================== CONFIG ==============================
// Mesmos recursos, lotes e janelas do cenario A (src/ingestao/), com duas
// diferencas documentadas no spec.md (secoes 6 e 8.2):
//   - agregados municipais sempre por ano x UF (N6[N3[uf]]), para respostas pequenas;
//   - ANO_INICIO: o n8n so cuida dos anos recentes; o historico completo e do cenario A.
const MODO = 'incremental';          // 'incremental' | 'inicial' (ignora o que ja foi salvo)
const ANO_INICIO = 2022;             // agregados municipais: lotes deste ano em diante
const DATA_INICIO_BCB = '2015-01-01';
const UFS = [11, 12, 13, 14, 15, 16, 17, 21, 22, 23, 24, 25, 26, 27, 28, 29,
             31, 32, 33, 35, 41, 42, 43, 50, 51, 52, 53];
const LOCALIDADES = [
  ['ibge_regioes', '/v1/localidades/regioes', {}],
  ['ibge_estados', '/v1/localidades/estados', {}],
  ['ibge_municipios', '/v1/localidades/municipios', { view: 'nivelado' }],
  ['ibge_malha_municipios', '/v4/malhas/paises/BR/metadados', { intrarregiao: 'municipio' }],
];
const AGREGADOS = {
  '6579': { variaveis: [9324] },
  '4714': { variaveis: [93, 6318, 614] },
  '10295': { variaveis: [13431], classificacao: '2[6794]|86[95251]|58[95253]' },
  '5938': { variaveis: [37], variaveis_extras: [498, 513, 517, 6575, 525, 543], extras_ate_ano: 2021 },
  '7060': { variaveis: [63, 2265], classificacao: '315[7169]', nivel: 'N1', agrupar_por_ano: true },
  '9509': { variaveis: [10143] },
  '9418': { variaveis: [2585], classificacao: '12762[117856]', timeout: 120 },
};
const SERIES_BCB = ['432', '10813', '433'];
// ====================================================================

const agendado = $('Segunda 07:00 (desligada)').isExecuted;
return [{ json: {
  modo: MODO, disparado_por: agendado ? 'agenda_n8n' : 'manual',
  ano_inicio: ANO_INICIO, data_inicio_bcb: DATA_INICIO_BCB, ufs: UFS,
  localidades: LOCALIDADES, agregados: AGREGADOS, series_bcb: SERIES_BCB,
} }];

// So monta URLs e parametros: nenhuma chamada de API e nenhum dado transformado aqui.
const cfg = $('Config').first().json;
const rodada_id = $('Pega a trava').first().json.rodada_id;
const salvos = $('Último período salvo (n8n)').all().map(i => i.json).filter(r => r.recurso);
const agregados = $('Agregados do CONFIG').all().map(i => i.json.agregado);
const IBGE = 'https://servicodados.ibge.gov.br/api';
const BCB = 'https://api.bcb.gov.br';
const hoje = DateTime.now().setZone('America/Sao_Paulo').startOf('day');

const recursos = {};
const rec = r => (recursos[r] ??= { chamadas_ok: 0, chamadas_erro: 0, mensagens: [] });
const chamadas = [];
const url = (base, endpoint, params) => {
  // (o sandbox do Code nao tem URLSearchParams)
  const q = Object.entries(params).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
  return base + endpoint + (q ? '?' + q : '');
};
const add = (c) => chamadas.push({ ...c, url: url(c.base, c.endpoint, c.params) });

// 1. Localidades: snapshot toda semana (barato)
for (const [recurso, endpoint, params] of cfg.localidades) {
  rec(recurso);
  add({ fonte: 'IBGE', recurso, base: IBGE, endpoint, params, parametros: params,
        lote: 'snapshot', modificacao: null, timeout_ms: 60000 });
}

// 2. Agregados: /periodos -> lotes novos ou modificados (mesma regra do cenario A)
const dataIbge = t => (t ? `${t.slice(6, 10)}-${t.slice(3, 5)}-${t.slice(0, 2)}` : null);
const precisaBaixar = (recurso, lote, modificacao) => {
  const datas = salvos.filter(s => s.recurso === recurso && (s.lote === lote || s.lote.startsWith(lote + '-')));
  if (!datas.length) return true;
  const recente = datas.map(s => s.modificacao_fonte).filter(Boolean).sort().at(-1);
  return modificacao !== null && (!recente || modificacao > recente);
};
$input.all().forEach((item, i) => {
  const ag = agregados[i];
  const a = cfg.agregados[ag];
  const recurso = `ibge_agregado_${ag}`;
  const r = rec(recurso);
  const resp = item.json;
  if (resp.error || resp.statusCode !== 200 || !Array.isArray(resp.body)) {
    r.chamadas_erro++;
    r.mensagens.push(`/periodos falhou: ${resp.error?.message ?? resp.statusCode}`);
    return;
  }
  r.chamadas_ok++;
  const lotes = {};
  for (const p of resp.body) {
    const chave = a.agrupar_por_ano ? p.id.slice(0, 4) : p.id;
    const l = (lotes[chave] ??= { periodos: [], modificacao: null });
    l.periodos.push(p.id);
    const m = dataIbge(p.modificacao);
    if (m && (!l.modificacao || m > l.modificacao)) l.modificacao = m;
  }
  const municipal = (a.nivel ?? 'N6') === 'N6';
  for (const lote of Object.keys(lotes).sort()) {
    const info = lotes[lote];
    const ano = Number(lote.slice(0, 4));
    if (municipal && ano < cfg.ano_inicio) continue;
    if (cfg.modo === 'incremental' && !precisaBaixar(recurso, lote, info.modificacao)) continue;
    const variaveis = [...a.variaveis, ...(a.variaveis_extras && ano <= a.extras_ate_ano ? a.variaveis_extras : [])];
    const endpoint = `/v3/agregados/${ag}/periodos/${info.periodos.join('|')}/variaveis/${variaveis.join('|')}`;
    const extra = a.classificacao ? { classificacao: a.classificacao } : {};
    const locais = municipal
      ? cfg.ufs.map(uf => [`${lote}-${uf}`, { localidades: `N6[N3[${uf}]]`, ...extra }])
      : [[lote, { localidades: 'N1[all]', ...extra }]];
    for (const [nomeLote, params] of locais) {
      add({ fonte: 'IBGE', recurso, base: IBGE, endpoint, params,
            parametros: { agregado: ag, periodos: info.periodos, variaveis, ...params },
            lote: nomeLote, modificacao: info.modificacao, timeout_ms: (a.timeout ?? 60) * 1000 });
    }
  }
});

// 3. BCB: incremental = ultima data salva (n8n) - 30 dias, sem data final; senao janelas de 10 anos
const br = d => d.toFormat('dd/MM/yyyy');
for (const serie of cfg.series_bcb) {
  const recurso = `bcb_sgs_${serie}`;
  rec(recurso);
  const endpoint = `/dados/serie/bcdata.sgs.${serie}/dados`;
  const ultima = cfg.modo === 'incremental'
    ? salvos.filter(s => s.recurso === recurso && s.ultima_data).map(s => s.ultima_data).sort().at(-1)
    : undefined;
  const janelas = [];
  if (ultima) {
    const u = DateTime.fromISO(ultima, { zone: 'America/Sao_Paulo' });
    janelas.push([(u < hoje ? u : hoje).minus({ days: 30 }), null]);
  } else {
    let atual = DateTime.fromISO(cfg.data_inicio_bcb, { zone: 'America/Sao_Paulo' });
    while (atual <= hoje) {
      const limite = atual.plus({ years: 10 }).minus({ days: 1 });
      janelas.push([atual, limite < hoje ? limite : hoje]);
      atual = limite.plus({ days: 1 });
    }
  }
  for (const [ini, fim] of janelas) {
    const params = { formato: 'json', dataInicial: br(ini), ...(fim ? { dataFinal: br(fim) } : {}) };
    add({ fonte: 'BCB', recurso, base: BCB, endpoint, params, parametros: { serie, ...params },
          lote: `${ini.toISODate()}_${fim ? fim.toISODate() : 'aberto'}`, modificacao: null, timeout_ms: 60000 });
  }
}

return [{ json: { rodada_id, modo: cfg.modo, disparado_por: cfg.disparado_por, recursos, chamadas } }];

const plano = $('Monta as chamadas').first().json;
const ids = Object.fromEntries($input.all().map(i => [i.json.recurso, i.json.execucao_id]));
return plano.chamadas.map(c => ({ json: { ...c, execucao_id: ids[c.recurso] } }));

// Junta o resultado de cada chamada por recurso e aplica a regra de status do spec.md (3.1).
const plano = $('Monta as chamadas').first().json;
const ids = Object.fromEntries($('Abre as execuções').all().map(i => [i.json.recurso, i.json.execucao_id]));
const enviados = $('Uma chamada por item').all();
const tot = {};
for (const [recurso, r] of Object.entries(plano.recursos)) {
  tot[recurso] = { execucao_id: ids[recurso], chamadas_ok: r.chamadas_ok, chamadas_erro: r.chamadas_erro,
                   respostas_novas: 0, mensagens: [...r.mensagens] };
}
$input.all().forEach((item, i) => {
  const enviado = enviados[i]?.json ?? {};
  const res = item.json;
  const t = tot[res.recurso ?? enviado.recurso];
  if (!t) return;
  if (res.resultado === 'nova' || res.resultado === 'ja_existia' || res.resultado === 'nada_novo') {
    t.chamadas_ok++;
    if (res.resultado === 'nova') t.respostas_novas++;
  } else {
    t.chamadas_erro++;
    t.mensagens.push(`${res.lote ?? enviado.lote}: ${res.mensagem ?? res.error?.message ?? 'erro no sub-workflow'}`);
  }
});
const linhas = Object.values(tot).map(t => ({
  execucao_id: t.execucao_id,
  status: t.chamadas_erro > 0 ? 'erro' : t.respostas_novas > 0 ? 'sucesso' : 'sem_novidade',
  mensagem: t.mensagens.length ? ('lotes com erro: ' + t.mensagens.join('; ')).slice(0, 1000) : null,
  chamadas_ok: t.chamadas_ok, chamadas_erro: t.chamadas_erro, respostas_novas: t.respostas_novas,
}));
return [{ json: { linhas } }];

const fech = $('Grava o fechamento').first().json;
const transformou = $('Transforma (radar-etl)').isExecuted;
let transformacao = 'não rodou: nenhuma resposta nova';
let ok_transf = true;
if (transformou) {
  const t = $('Transforma (radar-etl)').first().json;
  const corpo = t.body ?? {};
  ok_transf = t.statusCode === 200 && corpo.status === 'sucesso';
  transformacao = t.error ? `erro: ${t.error.message ?? t.error}` : `HTTP ${t.statusCode} ${corpo.status ?? ''} ${corpo.motivo ?? ''}`.trim();
}
const trava_solta = $('Solta a trava').all().some(i => i.json.trava_id);
const ok = Number(fech.com_erro) === 0 && ok_transf && trava_solta;
return [{ json: {
  ok, rodada_id: $('Pega a trava').first().json.rodada_id,
  recursos: Number(fech.recursos), respostas_novas: Number(fech.novas), recursos_com_erro: Number(fech.com_erro),
  detalhe_erros: fech.erros, transformacao, trava_solta,
} }];
